package com.callguard;
import android.app.Activity;import com.android.billingclient.api.*;import org.json.JSONObject;import java.util.*;import java.util.concurrent.ExecutorService;import java.util.function.Consumer;
final class ProBilling {
    private final Activity activity;private final ExecutorService worker;private final Consumer<String> message;private final BillingClient client;
    ProBilling(Activity a,ExecutorService worker,Consumer<String> message){this.activity=a;this.worker=worker;this.message=message;client=BillingClient.newBuilder(a).setListener((result,purchases)->{if(result.getResponseCode()==BillingClient.BillingResponseCode.OK&&purchases!=null)for(Purchase p:purchases)verify(p);else if(result.getResponseCode()==BillingClient.BillingResponseCode.ITEM_ALREADY_OWNED)restore();else if(result.getResponseCode()!=BillingClient.BillingResponseCode.USER_CANCELED)message.accept("Google Play satın alma işlemi tamamlanamadı.");}).enablePendingPurchases(PendingPurchasesParams.newBuilder().enableOneTimeProducts().build()).enableAutoServiceReconnection().build();}
    private void ready(Runnable action){if(client.isReady()){action.run();return;}client.startConnection(new BillingClientStateListener(){public void onBillingSetupFinished(BillingResult result){if(result.getResponseCode()==BillingClient.BillingResponseCode.OK)action.run();else message.accept("Google Play bağlantısı kurulamadı. Uygulamayı Play Store test kanalından yüklemek gerekir.");}public void onBillingServiceDisconnected(){}});}
    void purchase(){ready(()->{QueryProductDetailsParams params=QueryProductDetailsParams.newBuilder().setProductList(Collections.singletonList(QueryProductDetailsParams.Product.newBuilder().setProductId(BuildConfig.PRO_PRODUCT_ID).setProductType(BillingClient.ProductType.INAPP).build())).build();client.queryProductDetailsAsync(params,(result,details)->activity.runOnUiThread(()->{if(activity.isFinishing())return;if(result.getResponseCode()!=BillingClient.BillingResponseCode.OK||details.getProductDetailsList().isEmpty()){message.accept("Pro ürünü Play Store'da henüz etkin değil.");return;}ProductDetails product=details.getProductDetailsList().get(0);List<ProductDetails.OneTimePurchaseOfferDetails> offers=product.getOneTimePurchaseOfferDetailsList();if(offers==null||offers.isEmpty()){message.accept("Satın alma teklifi bulunamadı.");return;}ProductDetails.OneTimePurchaseOfferDetails offer=offers.get(0);new android.app.AlertDialog.Builder(activity).setTitle("CallGuard Pro · "+offer.getFormattedPrice()).setMessage("Tek ödeme, abonelik yok. Bütün özelliklere kalıcı erişim. Satın alma bu CallGuard hesabına bağlanır.").setNegativeButton("Vazgeç",null).setPositiveButton("Google Play ile satın al",(d,w)->{try{BillingFlowParams flow=BillingFlowParams.newBuilder().setObfuscatedAccountId(CloudClient.accountHash(activity)).setProductDetailsParamsList(Collections.singletonList(BillingFlowParams.ProductDetailsParams.newBuilder().setProductDetails(product).setOfferToken(offer.getOfferToken()).build())).build();BillingResult launch=client.launchBillingFlow(activity,flow);if(launch.getResponseCode()!=BillingClient.BillingResponseCode.OK)message.accept("Satın alma ekranı açılamadı.");}catch(Exception ex){message.accept("Hesap doğrulanamadı. Tekrar giriş yap.");}}).show();}));});}
    void restore(){ready(()->client.queryPurchasesAsync(QueryPurchasesParams.newBuilder().setProductType(BillingClient.ProductType.INAPP).build(),(result,purchases)->{if(result.getResponseCode()!=BillingClient.BillingResponseCode.OK){message.accept("Google Play satın almaları alınamadı.");return;}boolean found=false;for(Purchase p:purchases)if(p.getProducts().contains(BuildConfig.PRO_PRODUCT_ID)){found=true;verify(p);}if(!found)message.accept("Bu Google Play hesabında Pro satın alması bulunamadı.");}));}
    private void verify(Purchase p){if(!p.getProducts().contains(BuildConfig.PRO_PRODUCT_ID))return;if(p.getPurchaseState()==Purchase.PurchaseState.PENDING){message.accept("Ödeme bekleniyor. Tamamlandığında Pro etkinleşecek.");return;}if(p.getPurchaseState()!=Purchase.PurchaseState.PURCHASED)return;worker.execute(()->{try{JSONObject data=CloudClient.request(activity,"POST","/v1/purchase",new JSONObject().put("token",p.getPurchaseToken()),true);LicenseManager.cache(activity,data);activity.runOnUiThread(()->message.accept("Pro lisansın doğrulandı ve etkinleştirildi."));}catch(Exception ex){activity.runOnUiThread(()->message.accept("Satın alma henüz doğrulanamadı. Aynı hesapla Satın almayı geri yükle seçeneğini kullan."));}});}
    void close(){client.endConnection();}
}
